import {fmt,uid,isoDay,validateData,baseState,seedDemo,migrateLegacy,migrateLegacyBackup,productCreate,productEdit,supplierCreate,supplierEdit,customerCreate,customerEdit,createOrder,updateOrderStatus,receiveStock,payPurchase,auditStock,expenseSave,expenseDelete,decisionSave,financials,procurementSummary,supplierDebt,inventoryValue,monthlyRevenue,salesByProduct,forecast,scoreSuppliers,scenario,goalSeek,simpleRecommendation} from './core.mjs';
const KEY='smartdecision_v3_main';
let data;
try { const cached=JSON.parse(localStorage.getItem(KEY)||'null');data=cached?validateData(cached):seedDemo();}catch(err){console.warn('Storage error',err);data=seedDemo();}
const ui={page:'dashboard',filter:'',month:'all',forecastProduct:'',scenario:{pricePct:5,unitsPct:-3,costPct:0,expensesPct:0},goal:10000000,modal:'',editing:'',sidebar:false,chatOpen:false,chatInput:'',chatBusy:false,chat:[{role:'assistant',text:'Xin chào! Bạn muốn phân tích doanh thu, tồn kho, công nợ hay so sánh phương án kinh doanh?'}],chatPos:null};
try {ui.chatPos=JSON.parse(localStorage.getItem('smartdecision_v3_chatpos')||'null');ui.chatFabPos=JSON.parse(localStorage.getItem('smartdecision_v4_chatfabpos')||'null');}catch{}
const nav=[{group:'VẬN HÀNH',items:[['dashboard','▦','Tổng quan'],['orders','▤','Bán hàng & đơn hàng'],['products','◈','Danh mục sản phẩm'],['inventory','▣','Kho & kiểm kê'],['suppliers','♧','Nhà cung cấp & nhập hàng'],['customers','♙','Khách hàng'],['finance','◉','Tài chính & báo cáo']]},{group:'HỖ TRỢ RA QUYẾT ĐỊNH',items:[['analytics','▥','Phân tích kinh doanh'],['forecast','⌁','Dự báo nhu cầu'],['scenarios','◇','Mô phỏng quyết định'],['ranking','⚖','So sánh nhà cung cấp'],['decisions','◎','Theo dõi quyết định']]},{group:'HỆ THỐNG',items:[['settings','⚙','Cài đặt doanh nghiệp']]}];
const titles={...Object.fromEntries(nav.flatMap(g=>g.items.map(i=>[i[0],i[2]]))),alerts:'Cảnh báo cần xử lý'};
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const integer=x=>new Intl.NumberFormat('vi-VN').format(Number(x)||0);
const productName=id=>data.products.find(p=>p.id===id)?.name||'Sản phẩm đã xóa';
const supplierName=id=>data.suppliers.find(x=>x.id===id)?.name||'Không xác định';
const customerName=id=>data.customers.find(x=>x.id===id)?.name||'Khách hàng cũ';
const money=x=>fmt(x);
const badge=(s)=>{const tone=/(Hoàn thành|Đã duyệt|Đủ hàng)/.test(s)?'ok':/(Đã hủy|Hủy|Thiếu hàng|Quá hạn)/.test(s)?'bad':'warn';return `<span class="status status-${tone}">${safe(s)}</span>`;};
const btn=(text,act,cls='secondary',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${act}" ${attrs}>${text}</button>`;
const date=s=>{if(!s)return '—';if(/^\d{4}-\d{2}-\d{2}/.test(s)){const [y,m,d]=s.slice(0,10).split('-');return `${d}/${m}/${y}`;}return safe(s);};
const card=(label,val,desc,icon='◇',tone='blue')=>`<div class="metric"><div class="metric-icon ${tone}">${icon}</div><div class="metric-label">${label}</div><strong>${val}</strong><small>${desc||'Theo dữ liệu hiện có'}</small></div>`;
const panel=(title,body,aside='')=>`<section class="panel"><div class="panel-title"><h2>${title}</h2>${aside}</div>${body}</section>`;
const empty=(t='Chưa có dữ liệu phù hợp.')=>`<div class="empty">⌁<p>${safe(t)}</p></div>`;
const td=x=>`<td>${x}</td>`;
const table=(headers,rows)=>`<div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">${empty()}</td></tr>`}</tbody></table></div>`;
const tableRow=c=>`<tr>${c.map(td).join('')}</tr>`;
const company=()=>safe(data.company.name||'Doanh nghiệp chưa đặt tên');
function setData(v,toast='Đã lưu thay đổi.') {data=validateData(v);try{localStorage.setItem(KEY,JSON.stringify(data));}catch{notice('Không thể lưu vào bộ nhớ trình duyệt. Hãy xuất bản sao lưu.','bad');}render();notice(toast);}
function notice(message,tone='ok'){const t=document.getElementById('toast');if(!t)return;t.className=`toast show ${tone}`;t.textContent=message;clearTimeout(notice.timer);notice.timer=setTimeout(()=>{t.className='toast';},4400);}
let lastMutationOk=true;function transactional(fn,msg){try{setData(fn(data),msg);lastMutationOk=true;return true;}catch(e){lastMutationOk=false;notice(e.message||'Dữ liệu không hợp lệ.','bad');return false;}}
function main(){const f=financials(data),r=simpleRecommendation(data);const trend=monthlyRevenue(data,6);const max=Math.max(...trend.map(x=>x.revenue),1);const issues=[...(r.low.length?[`${r.low.length} mặt hàng đang chạm ngưỡng tồn kho`]:[]),...(r.unverified?[`${r.unverified} đơn cũ thiếu giá vốn để tính lợi nhuận`]:[]),...(r.debts.length?[`${r.debts.length} nhà cung cấp đang có công nợ`]:[])];return `<div class="metrics">${card('Doanh thu hoàn thành',money(f.revenue),'Không cộng số liệu ước lượng','↗','green')}${card('Giá vốn đã xác minh',money(f.cogsKnown),`${f.missing.length} đơn thiếu giá vốn`,'▥','purple')}${card('Giá trị tồn kho',money(inventoryValue(data)),'Theo số lượng × giá vốn hiện tại','▣','blue')}${card('Lợi nhuận sau chi phí',f.net===null?'Chưa đủ dữ liệu':money(f.net),f.net===null?'Có đơn cũ chưa xác minh giá vốn':'Chưa gồm thuế và lãi vay','◉','orange')}</div><div class="columns two-thirds">${panel('Doanh thu theo 6 tháng',`<div class="chart">${trend.map(z=>`<div class="chart-col"><div class="chart-bar-wrap"><div class="chart-bar" title="${money(z.revenue)}" style="height:${Math.max(z.revenue?6:0,z.revenue/max*100)}%"></div></div><b>${safe(z.label)}</b><small>${z.revenue?integer(Math.round(z.revenue/1000))+'k':'0'}</small></div>`).join('')}</div><p class="caption">Chỉ tính đơn hoàn thành theo ngày bán; không sử dụng cột số liệu dựng sẵn.</p>`)}${panel('Việc cần ưu tiên',issues.length?`<div class="issue-list">${issues.map(x=>`<div><span class="issue-dot"></span>${safe(x)}</div>`).join('')}</div>${btn('Xem chi tiết và xử lý','go-alerts','compact')}`:empty('Chưa phát hiện cảnh báo dựa trên ngưỡng đang cấu hình.'))}</div><div class="columns half">${panel('Sản phẩm bán chạy',table(['Sản phẩm','Số lượng','Doanh thu'],salesByProduct(data).filter(x=>x.units>0).slice(0,5).map(x=>tableRow([safe(x.name),integer(x.units),money(x.revenue)]))))}${panel('Đơn hàng gần đây',table(['Mã đơn','Khách hàng','Tổng','Trạng thái'],data.orders.slice(0,5).map(x=>tableRow([`<span class="code">${safe(x.id)}</span>`,safe(x.customerName||customerName(x.customerId)),money(x.total),badge(x.status)]))))}</div>`;}
function pageOrders(){const rows=data.orders.filter(o=>search(o.id+' '+o.customerName+' '+o.status));return `${head('Quy trình bán hàng','Một đơn có thể có nhiều sản phẩm. Hoàn thành mới xuất kho; hoàn kho khi đổi khỏi trạng thái hoàn thành.',btn('＋ Tạo đơn hàng','new-order','primary'))}${panel('Danh sách đơn hàng',table(['Mã / ngày','Khách hàng','Chi tiết','Tổng tiền','Trạng thái','Thao tác'],rows.map(o=>tableRow([`<span class="code">${safe(o.id)}</span><small>${date(o.date)}</small>`,safe(o.customerName||customerName(o.customerId)),o.lines?.length?o.lines.map(l=>`${safe(l.name||productName(l.productId))} × ${integer(l.quantity)}`).join('<br>'):'<span class="subtle">Đơn cũ thiếu dòng SKU</span>',`<strong>${money(o.total)}</strong>`,badge(o.status),`<select aria-label="Trạng thái đơn hàng" data-order-status="${safe(o.id)}"><option ${o.status==='Đang xử lý'?'selected':''}>Đang xử lý</option><option ${o.status==='Hoàn thành'?'selected':''}>Hoàn thành</option><option ${o.status==='Đã hủy'?'selected':''}>Đã hủy</option></select>`]))))}<p class="caption">Đơn lịch sử không có dòng hàng vẫn sửa được trạng thái, nhưng hệ thống không đoán lượng tồn kho cần điều chỉnh.</p>`;}
function pageProducts(){return `${head('Danh mục sản phẩm','Chỉ quản lý sản phẩm, giá, phân loại và nhà cung cấp. Nhập / xuất hàng thực hiện tại Kho.',btn('＋ Thêm sản phẩm','new-product','primary'))}${panel('Sản phẩm đang quản lý',table(['Mã SKU','Sản phẩm','Danh mục','Giá bán','Giá vốn bình quân','Nhà cung cấp','Tồn hiện tại','Thao tác'],data.products.filter(p=>search(p.name+' '+p.sku+' '+p.category)).map(p=>tableRow([`<span class="code">${safe(p.sku)}</span>`,`<strong>${safe(p.name)}</strong><small>${p.active===false?'Ngừng bán':'Đang bán'}</small>`,safe(p.category),money(p.price),p.cost?money(p.cost):'<span class="muted">Chưa nhập kho</span>',safe(supplierName(p.supplierId)),integer(p.stock),btn('Sửa','edit-product','compact',`data-id="${safe(p.id)}"`)]))))}<p class="caption">Giá vốn tham khảo là bình quân hiện tại sau nhập kho. Đơn đã hoàn thành giữ nguyên giá vốn chụp tại thời điểm bán.</p>`;}
function pageInventory(){const low=data.products.filter(p=>p.stock<=p.min&&p.active!==false);return `<div class="metrics three">${card('Sản phẩm đang theo dõi',integer(data.products.length),'SKU trong danh mục','▦')}${card('Giá trị tồn kho',money(inventoryValue(data)),'Giá vốn × tồn hiện tại','◈','green')}${card('Cảnh báo thiếu hàng',integer(low.length),'Tồn không lớn hơn ngưỡng','⚑','orange')}</div>${head('Nhập kho & kiểm kê','Luồng riêng biệt: nhận hàng từ nhà cung cấp, ghi công nợ, điều chỉnh tồn và xem nhật ký.',`${btn('＋ Tạo phiếu nhập tại Nhà cung cấp','go-purchase','primary')} ${btn('Kiểm kê','audit')}`)}${panel('Tồn kho theo SKU',table(['SKU','Sản phẩm','Tồn','Ngưỡng','Trạng thái','Vốn cần bổ sung tới ngưỡng'],data.products.filter(p=>search(p.name+' '+p.sku)).map(p=>tableRow([`<span class="code">${safe(p.sku)}</span>`,safe(p.name),integer(p.stock),integer(p.min),badge(p.stock<=p.min?'Thiếu hàng':'Đủ hàng'),money(Math.max(0,p.min-p.stock)*p.cost)]))))}${panel('Nhật ký nhập / xuất / kiểm kê',table(['Ngày','Nghiệp vụ','Tham chiếu','Biến động','Lý do'],data.stockLedger.slice(0,40).map(x=>tableRow([date(x.date),badge(x.type),`<span class="code">${safe(x.ref)}</span>`,(x.lines||[]).map(l=>`${safe(productName(l.productId))}: ${l.quantity>0?'+':''}${integer(l.quantity)}`).join('<br>'),safe(x.reason||'—')]))))}`;}
function pageSuppliers(){return `${head('Nhà cung cấp & nhập hàng','Một phiếu nhập cập nhật kho, giá vốn và công nợ. Mọi thao tác mua hàng thực hiện tại đây.',`${btn('＋ Nhà cung cấp','new-supplier','primary')} ${btn('＋ Tạo phiếu nhập','receive','primary')} ${btn('Thanh toán công nợ','pay')} ${btn('So sánh NCC','go-ranking')}`)}<div class="metrics three">${card('Nhà cung cấp',integer(data.suppliers.length),'Được liên kết với sản phẩm','♧')}${card('Tổng công nợ',money(data.suppliers.reduce((z,s)=>z+supplierDebt(data,s.id),0)),'Chỉ công nợ từ phiếu mua','◉','orange')}${card('Phiếu mua',integer(data.purchases.length),'Lịch sử chứng từ','▥')}</div>${panel('Danh sách nhà cung cấp',table(['Nhà cung cấp','Liên hệ','Số SKU liên kết','Công nợ từ phiếu','Thao tác'],data.suppliers.filter(s=>search(s.name)).map(s=>tableRow([`<strong>${safe(s.name)}</strong><small>${safe(s.id)}</small>`,safe(s.phone||'—'),integer(data.products.filter(p=>p.supplierId===s.id).length),`<strong>${money(supplierDebt(data,s.id))}</strong>`,btn('Sửa','edit-supplier','compact',`data-id="${safe(s.id)}"`)]))))}${panel('Chứng từ mua hàng & thanh toán',table(['Phiếu mua','Nhà cung cấp','Sản phẩm','Giá mua hàng','Phí nhập kho','Giá trị nhập kho','Phải trả NCC','Đã trả NCC','Còn nợ','Hóa đơn'],data.purchases.map(p=>tableRow([`<span class="code">${safe(p.id)}</span><small>${date(p.date)}</small>`,safe(supplierName(p.supplierId)),safe(productName(p.productId)),money(p.merchandiseTotal??p.total),money((p.freight||0)+(p.handling||0)),money(p.landedTotal??p.total),money(p.total),money(p.paid),`<strong>${money(p.total-p.paid)}</strong>`,btn('Xem chứng từ','view-evidence','compact',`data-id="purchase:${safe(p.id)}"`)]))))}${panel('Lịch sử các lần thanh toán',table(['Ngày','Phiếu mua','Nhà cung cấp','Số tiền thanh toán','Chứng từ'],data.purchases.flatMap(p=>(p.payments||[]).map(pay=>tableRow([date(pay.date),`<span class="code">${safe(p.id)}</span>`,safe(supplierName(p.supplierId)),money(pay.amount),btn('Xem chứng từ','view-evidence','compact',`data-id="payment:${safe(pay.id)}"`)])))))}<p class="caption">Thanh toán công nợ không làm giảm lợi nhuận lần thứ hai. Giao dịch đã lưu có lịch sử thanh toán.</p>`;}
function pageCustomers(){return `${head('Khách hàng & lịch sử mua','Hồ sơ khách hàng liên kết trực tiếp với đơn hàng và doanh thu đã hoàn thành.',btn('＋ Thêm khách hàng','new-customer','primary'))}${panel('Giá trị khách hàng',table(['Khách hàng','Liên hệ','Tổng đơn','Đơn hoàn thành','Doanh thu đã ghi nhận','Thao tác'],data.customers.filter(c=>search(c.name+' '+c.phone)).map(c=>{const od=data.orders.filter(o=>o.customerId===c.id);return tableRow([`<strong>${safe(c.name)}</strong><small>${safe(c.id)}</small>`,safe(c.phone||c.email||'—'),integer(od.length),integer(od.filter(o=>o.status==='Hoàn thành').length),money(od.filter(o=>o.status==='Hoàn thành').reduce((z,o)=>z+Number(o.total),0)),btn('Sửa','edit-customer','compact',`data-id="${safe(c.id)}"`)]);})))}`;}
function monthOptions(){const set=new Set([new Date().toISOString().slice(0,7),...data.expenses.map(e=>String(e.date).slice(0,7)),...data.orders.map(o=>String(o.date).slice(0,7)),...data.purchases.map(p=>String(p.date).slice(0,7)),...data.purchases.flatMap(p=>(p.payments||[]).map(x=>String(x.date).slice(0,7)))].filter(x=>/^\d{4}-\d\d$/.test(x)));return `<select aria-label="Chọn kỳ tài chính" data-filter-month><option value="all" ${ui.month==='all'?'selected':''}>Toàn bộ dữ liệu</option>${[...set].sort().reverse().map(m=>`<option value="${m}" ${ui.month===m?'selected':''}>Tháng ${m.slice(5)}/${m.slice(0,4)}</option>`).join('')}</select>`;}
function pageFinance(){const f=financials(data,ui.month),p=procurementSummary(data,ui.month);return `${head('Tài chính & báo cáo','Lợi nhuận và dòng tiền nhập hàng được theo dõi riêng, không trừ hai lần tiền mua hàng.',`${monthOptions()} ${btn('＋ Ghi chi phí','new-expense','primary')} ${btn('✦ AI phân tích tài chính','finance-ai','primary')} ${btn('Xuất báo cáo CSV','export-report')}`)}<div class="metrics">${card('Doanh thu',money(f.revenue),`${f.orders} đơn hoàn thành`,'↗','green')}${card('Giá vốn xác minh',money(f.cogsKnown),`${f.missing.length} đơn thiếu giá vốn`,'▤')}${card('Chi phí vận hành',money(f.expenses),'Không bao gồm nhập kho','↘','orange')}${card('Lợi nhuận sau chi phí',f.net===null?'Không đủ dữ liệu':money(f.net),f.missing.length?'Chưa thể xác nhận tổng lợi nhuận':'Trước thuế / lãi vay','◉',f.net===null?'orange':'green')}</div>${panel('Tiền mua hàng & công nợ (không trừ trực tiếp vào lợi nhuận)',`<div class="procurement-summary"><div><small>Tiền hàng nhập trong kỳ</small><strong>${money(p.purchaseValue)}</strong></div><div><small>Phí nhập kho đã phân bổ</small><strong>${money(p.landed-p.purchaseValue)}</strong></div><div><small>Đã trả nhà cung cấp trong kỳ</small><strong>${money(p.paidSupplier)}</strong></div><div><small>Phí bên ngoài đã trả khi nhập</small><strong>${money(p.paidExternal)}</strong></div><div><small>Tổng chi tiền nhập hàng trong kỳ</small><strong>${money(p.paidSupplier+p.paidExternal)}</strong></div><div class="outflow-total"><small>TỔNG TIỀN CHI ĐÃ GHI NHẬN (mua hàng + vận hành)</small><strong>${money(p.paidSupplier+p.paidExternal+f.expenses)}</strong></div><div><small>Công nợ NCC hiện tại</small><strong>${money(p.debtOutstanding)}</strong></div></div><p class="caption">Tiền nhập hàng tự động tăng dòng tiền chi khi thanh toán, nhưng không làm giảm ngay lợi nhuận. Giá trị hàng tồn sẽ đi vào giá vốn khi bán. Phí vận chuyển về kho được phân bổ vào giá vốn, không nhập lại vào chi phí hoạt động. ${btn('Xem phiếu nhập & thanh toán','go-purchase','compact')}</p>`)}${f.missing.length?`<div class="notice-warn"><strong>Thiếu cơ sở tính lợi nhuận:</strong> ${f.missing.length} đơn hoàn thành không có đầy đủ dòng hàng / giá vốn. Doanh thu vẫn được ghi nhận, nhưng không thể tính tổng lợi nhuận chính xác. <small>Đơn: ${f.missing.slice(0,6).map(safe).join(', ')}</small></div>`:''}<div class="columns half">${panel('Công thức tài chính',`<div class="formula"><div><span>Doanh thu hoàn thành</span><strong>${money(f.revenue)}</strong></div><div><span>Giá vốn đã biết</span><strong>− ${money(f.cogsKnown)}</strong></div><div><span>Chi phí hoạt động</span><strong>− ${money(f.expenses)}</strong></div><div class="formula-result"><span>Kết quả kinh doanh</span><strong>${f.net===null?'Chưa xác định':money(f.net)}</strong></div></div><p class="caption">Không bao gồm thuế, chi phí lãi vay và hàng trả lại ngoài quy trình đổi trạng thái.</p>`)}${panel('Cơ cấu chi phí',(()=>{const m={};for(const x of f.expenseRows)m[x.category]=(m[x.category]||0)+x.amount;const max=Math.max(...Object.values(m),1);return Object.entries(m).length?Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([cat,value])=>`<div class="expense-bar"><span>${safe(cat)}</span><strong>${money(value)}</strong><div><i style="width:${value/max*100}%"></i></div></div>`).join(''):empty();})())}</div>${panel('Các khoản chi đã ghi nhận',table(['Ngày','Tên khoản chi','Nhóm chi phí','Số tiền','Thao tác'],f.expenseRows.filter(e=>search(e.name+' '+e.category)).map(e=>tableRow([date(e.date),safe(e.name),safe(e.category),money(e.amount),`${btn('Sửa','edit-expense','compact',`data-id="${safe(e.id)}"`)} ${btn('Xóa','delete-expense','compact danger',`data-id="${safe(e.id)}"`)}`]))))}`;}
function pageAnalytics(){const sales=salesByProduct(data).filter(z=>z.units>0);const trend=monthlyRevenue(data,6);const categories={};for(const x of sales){const p=data.products.find(p=>p.id===x.productId);const key=p?.category||'Khác';categories[key]=(categories[key]||0)+x.revenue;}const total=Object.values(categories).reduce((z,x)=>z+x,0);return `${head('Phân tích kinh doanh','Dữ liệu đã ghi nhận — không dùng ước lượng doanh thu theo SKU cho đơn lịch sử thiếu dòng hàng.')}${panel('Xu hướng 6 tháng',table(['Tháng','Doanh thu','Chi phí hoạt động','Tỷ lệ chi phí / doanh thu'],trend.map(x=>tableRow([x.month,money(x.revenue),money(x.expenses),x.revenue?(x.expenses/x.revenue*100).toFixed(1)+'%':'—']))))}<div class="columns half">${panel('Hiệu quả theo sản phẩm',table(['Sản phẩm','Số lượng bán','Doanh thu'],sales.map(x=>tableRow([safe(x.name),integer(x.units),money(x.revenue)]))))}${panel('Đóng góp doanh thu theo danh mục',total?Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="expense-bar"><span>${safe(name)}</span><strong>${(100*value/total).toFixed(1)}%</strong><div><i style="width:${value/total*100}%"></i></div></div>`).join(''):empty('Chưa có đơn hoàn thành với dòng sản phẩm hợp lệ.'))}</div>`;}
function pageForecast(){if(!ui.forecastProduct&&data.products.length)ui.forecastProduct=data.products[0].id;const p=data.products.find(p=>p.id===ui.forecastProduct);const v=p?forecast(data,p.id):null;return `${head('Dự báo nhu cầu','Phương pháp tốc độ tiêu thụ trong 30 ngày quan sát; chỉ dùng khi có ít nhất ba đơn có ngày và SKU.')}${panel('Chọn mặt hàng',`<div class="row-control"><label>SKU cần dự báo</label><select data-forecast-product>${data.products.map(x=>`<option value="${safe(x.id)}" ${ui.forecastProduct===x.id?'selected':''}>${safe(x.name)}</option>`).join('')}</select></div>`)}${v?`<div class="metrics three">${card('Đã bán trong kỳ',integer(v.units)+' sp','30 ngày tính tới đơn mới nhất','▤')}${card('Nhu cầu 30 ngày dự kiến',integer(v.next30)+' sp','Nếu tốc độ bán giữ nguyên','⌁','purple')}${card('Nên cân nhắc nhập thêm',integer(Math.max(0,v.next30+(p?.min||0)-(p?.stock||0)))+' sp','Dự kiến nhu cầu + ngưỡng − tồn','▣','orange')}</div>${panel('Căn cứ mô hình',`<p><strong>Phương pháp:</strong> ${safe(v.method)}. Trung bình ${v.averageDaily.toFixed(2)} sản phẩm/ngày; có ${v.sampleOrders} đơn trong kỳ.</p><p class="caption">Đây là phép ngoại suy tuyến tính, không phải mô hình dự báo mùa vụ. Chưa tính lead time, trả hàng hoặc đơn chờ xử lý. Phương án nhập cần phê duyệt thủ công.</p>${btn('Lưu phương án dự báo thành quyết định','forecast-to-decision','primary',`data-id="${safe(p.id)}"`)}`)}`:`${panel('Chưa đủ lịch sử',`<div class="notice-warn">Chưa đủ ≥ 3 đơn hoàn thành có ngày hợp lệ và dòng SKU trong cửa sổ quan sát. Hệ thống không tạo số dự báo giả.</div><p>Hãy ghi nhận bán hàng thật theo thời gian để mô hình có căn cứ.</p>`)}`}`;}
function pageScenarios(){const sc=scenario(data,ui.scenario,ui.month),goal=goalSeek(data,ui.goal,ui.month),f=financials(data,ui.month);return `${head('Mô phỏng What-if & Goal-seeking','Điều chỉnh giả định và so sánh kết quả; mô hình chỉ chạy khi biết đầy đủ giá vốn.')}${panel('Thay đổi các giả định',`<form id="scenario-form" class="scenario-grid"><label>Giá bán thay đổi (%)<input name="pricePct" type="number" step="1" min="-80" max="100" value="${ui.scenario.pricePct}" /></label><label>Số lượng bán thay đổi (%)<input name="unitsPct" type="number" step="1" min="-100" max="200" value="${ui.scenario.unitsPct}" /></label><label>Giá vốn / đơn vị (%)<input name="costPct" type="number" step="1" min="-80" max="200" value="${ui.scenario.costPct}" /></label><label>Chi phí vận hành (%)<input name="expensesPct" type="number" step="1" min="-100" max="200" value="${ui.scenario.expensesPct}" /></label><button type="submit" class="btn primary">Tính lại phương án</button></form>`)}${sc?`<div class="metrics three">${card('Lợi nhuận cơ sở',money(sc.baseNet),'Từ giao dịch hoàn thành','◉')}${card('Lợi nhuận phương án',money(sc.net),'Theo giả định đã chọn','◇','purple')}${card('Chênh lệch',`${sc.change>=0?'+':''}${money(sc.change)}`,'Không phải dự báo doanh thu chắc chắn','↗',sc.change>=0?'green':'orange')}</div>`:`<div class="notice-warn">Không thể mô phỏng lợi nhuận vì còn ${f.missing.length} đơn thiếu giá vốn. Cần bổ sung dữ liệu hợp lệ, không tự đoán số liệu.</div>`}${sc?`<div class="decision-prompt"><strong>Đưa phương án vào quy trình phê duyệt</strong><p>Lưu giả định và kết quả mô phỏng để so sánh với thực tế sau khi thực hiện.</p>${btn('Lưu mô phỏng thành quyết định','scenario-to-decision','primary')}</div>`:''}${panel('Tìm doanh thu mục tiêu (Goal-seeking)',`<form id="goal-form" class="row-control"><label>Mục tiêu lợi nhuận trước thuế (₫)<input type="number" name="goal" min="0" step="1" value="${ui.goal}"></label><button class="btn primary" type="submit">Tính doanh thu cần đạt</button></form>${goal?`<div class="result-box"><div><span>Doanh thu tối thiểu cần đạt</span><strong>${money(goal.requiredRevenue)}</strong></div><div><span>Doanh thu cần tăng thêm so với hiện tại</span><strong>${money(goal.moreRevenue)}</strong></div><p class="caption">Biên đóng góp: ${(goal.margin*100).toFixed(1)}%. ${goal.assumption}</p></div>`:`<p class="caption">Chưa đủ dữ liệu xác thực hoặc biên đóng góp không dương để giải bài toán.</p>`}`)}`;}
function pageRanking(){let rank=[];try{rank=scoreSuppliers(data)}catch{}return `${head('Đánh giá nhà cung cấp đa tiêu chí','Chấm điểm 1–5 (cao hơn là tốt hơn) theo giá, thời gian giao và chất lượng. Trọng số do quản lý lựa chọn.')}${panel('Trọng số đánh giá',`<form id="weights-form" class="row-control"><label>Giá (%)<input type="number" name="price" min="0" max="100" step="1" value="${data.weights.price}"></label><label>Giao hàng (%)<input type="number" name="delivery" min="0" max="100" step="1" value="${data.weights.delivery}"></label><label>Chất lượng (%)<input type="number" name="quality" min="0" max="100" step="1" value="${data.weights.quality}"></label><button type="submit" class="btn primary">Cập nhật trọng số</button></form><p class="caption">Trọng số được chuẩn hóa theo tổng, không bắt buộc tổng bằng 100. Chỉ nhà cung cấp đã được bạn chấm điểm mới xuất hiện trong xếp hạng. Điểm là nhận định quản lý, không phải dữ liệu đo tự động.</p>`)}${panel('Ma trận đánh giá và xếp hạng',table(['Xếp hạng','Nhà cung cấp','Giá','Giao hàng','Chất lượng','Điểm tổng hợp','Thao tác'],rank.map((s,i)=>tableRow([`<strong>#${i+1}</strong>`,safe(s.name),integer(s.ratings.price)+'/5',integer(s.ratings.delivery)+'/5',integer(s.ratings.quality)+'/5',`<strong>${s.score.toFixed(2)}/5</strong>`,`${btn('Chấm điểm','rate-supplier','compact',`data-id="${safe(s.id)}"`)} ${btn('Nhập hàng','buy-from-supplier','compact',`data-id="${safe(s.id)}"`)}`]))))}${data.suppliers.some(x=>!data.ratings[x.id])?panel('Chưa chấm điểm',data.suppliers.filter(x=>!data.ratings[x.id]).map(x=>`<div class="unrated-row"><strong>${safe(x.name)}</strong>${btn('Chấm điểm','rate-supplier','compact',`data-id="${safe(x.id)}"`)}</div>`).join('')):''}${rank.length?`<div class="decision-prompt"><strong>Phương án dẫn đầu: ${safe(rank[0].name)}</strong><p>Điểm tổng hợp ${rank[0].score.toFixed(2)}/5 theo trọng số và điểm đã nhập. Điểm số là đánh giá chủ quan, cần kiểm chứng bằng dữ liệu thực.</p>${btn('Lưu đề xuất thành quyết định','rank-to-decision','primary')}</div>`:''}`;}
function pageAlerts(){const r=simpleRecommendation(data);const list=[...r.low.map(p=>({severity:'high',title:`Tồn kho thấp: ${p.name}`,desc:`Còn ${p.stock}, ngưỡng ${p.min}; cần bổ sung tối thiểu ${Math.max(0,p.min-p.stock)} đơn vị tới ngưỡng.`,act:'suggest-replenishment',id:p.id})),...r.debts.map(p=>({severity:'medium',title:`Công nợ: ${p.name}`,desc:`Còn ${money(p.debt)} từ phiếu mua chưa thanh toán.`,act:'go-payment'})),...(r.unverified?[{severity:'high',title:'Thiếu dữ liệu giá vốn',desc:`Có ${r.unverified} đơn hoàn thành chưa đủ chi tiết để kết luận tổng lợi nhuận.`,act:'go-finance'}]:[])];return `${head('Cảnh báo kinh doanh','Cảnh báo từ các điều kiện có thể kiểm chứng; không giả định đây là thông báo AI.')}${panel('Danh sách cảnh báo theo mức độ',list.length?`<div class="alert-list">${list.map(x=>`<div class="alert-item ${x.severity}"><span>⚑</span><div><strong>${safe(x.title)}</strong><p>${safe(x.desc)}</p></div>${btn('Xử lý →',x.act,'compact',x.id?`data-id="${safe(x.id)}"`:'')}</div>`).join('')}</div>`:empty('Không có cảnh báo với dữ liệu và ngưỡng hiện tại.'))}`;}
function pageDecisions(){return `${head('Vòng đời quyết định','Ghi nhận vấn đề → phương án → phê duyệt → thực hiện → so sánh mục tiêu và kết quả.',btn('＋ Tạo quyết định','new-decision','primary'))}${panel('Hồ sơ quyết định',table(['Quyết định','Căn cứ / kết quả kỳ vọng','Người phụ trách','Hạn','Trạng thái','Thao tác'],data.decisions.filter(d=>search(d.title+' '+d.reason)).map(d=>tableRow([`<strong>${safe(d.title)}</strong><small>${safe(d.id)}</small>`,`<span class="small-text">${safe(d.reason)}</span><small>Kỳ vọng: ${safe(d.expected||'Chưa xác định')}<br>Thực tế: ${safe(d.actual||'Chưa đánh giá')}</small>`,safe(d.owner),date(d.due),badge(d.status),btn('Cập nhật','edit-decision','compact',`data-id="${safe(d.id)}"`)]))))}`;}

function pageSettings(){return `${head('Hồ sơ và cấu hình doanh nghiệp','Đổi tên doanh nghiệp sẽ cập nhật tên trên menu và báo cáo, đồng thời được lưu vào dữ liệu.')}${panel('Thông tin doanh nghiệp',`<form id="settings-form" class="form-grid"><label>Tên doanh nghiệp / cửa hàng<input name="name" required maxlength="120" value="${safe(data.company.name)}"></label><label>Ngành nghề<input name="sector" maxlength="100" value="${safe(data.company.sector||'')}"></label><label>Số điện thoại<input name="phone" maxlength="40" value="${safe(data.company.phone||'')}"></label><label>Email<input name="email" type="email" maxlength="120" value="${safe(data.company.email||'')}"></label><label class="wide">Địa chỉ<input name="address" maxlength="240" value="${safe(data.company.address||'')}"></label><div class="wide"><button type="submit" class="btn primary">Lưu thông tin doanh nghiệp</button></div></form>`)}${panel('Dữ liệu & sao lưu',`<p class="muted">Phiên bản này lưu giao dịch trong <strong>trình duyệt hiện tại</strong>. Chưa đồng bộ giữa các máy; không bật ghi công khai vào Supabase. Hãy xuất bản sao lưu trước khi xóa dữ liệu trình duyệt. Chứng từ ảnh/PDF lưu cục bộ (IndexedDB) và được kèm trong bản sao lưu JSON đầy đủ; không đồng bộ sang thiết bị khác.</p><div class="settings-actions">${btn('↓ Xuất bản sao lưu JSON','backup','primary')}${btn('↑ Nhập sao lưu v3 / bản cũ','restore')}${btn('↗ Chuyển dữ liệu từ phiên bản cũ','migrate')}${btn('Khởi tạo dữ liệu mẫu','reset-demo')}${btn('Bắt đầu dữ liệu trống','reset-empty','danger')}</div><input type="file" id="restore-file" accept="application/json,.json" hidden><p class="caption">Mã dữ liệu phiên bản mới: smartdecision_v3_main. Có thể chuyển trực tiếp từ localStorage trên cùng trình duyệt / tên miền, hoặc tải lên tệp sao lưu smartdecision-local-v1 cũ. Các giao dịch lịch sử thiếu giá vốn sẽ tiếp tục được ghi nhãn chưa xác minh.</p>`)}}`;}
function head(label,subtitle,action=''){return `<div class="section-intro"><div><h2>${label}</h2><p>${subtitle}</p></div><div class="actions">${action}</div></div>`;}
function search(t){return String(t||'').toLowerCase().includes(ui.filter.toLowerCase());}
const pages={dashboard:main,orders:pageOrders,products:pageProducts,inventory:pageInventory,suppliers:pageSuppliers,customers:pageCustomers,finance:pageFinance,analytics:pageAnalytics,forecast:pageForecast,scenarios:pageScenarios,ranking:pageRanking,alerts:pageAlerts,decisions:pageDecisions,settings:pageSettings};
function render(){const previousScroll=typeof window.scrollY==='number'?window.scrollY:0;const sidebarScroll=document.querySelector('.sidebar')?.scrollTop??0;document.title=`${titles[ui.page]} · SmartDecision`;const root=document.getElementById('app');root.innerHTML=`<div class="shell"><aside class="sidebar ${ui.sidebar?'mobile-open':''}"><div class="brand"><div class="brand-mark" aria-hidden="true"><svg viewBox="0 0 48 48" width="37" height="37" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M10 35L21 24L29 30L40 13" stroke="#FAFBFF" stroke-width="3.6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="10" cy="35" r="4" fill="#8FE6D3"/><circle cx="21" cy="24" r="4" fill="#E7E9FF"/><circle cx="29" cy="30" r="4" fill="#A7B1FF"/><circle cx="40" cy="13" r="4" fill="#8FE6D3"/></svg></div><div><strong>SmartDecision</strong><small>DATA · MODEL · DECISION</small></div></div><div class="org-chip"><div class="org-icon">⌂</div><div><span>DOANH NGHIỆP</span><strong title="${company()}">${company()}</strong></div></div><nav>${nav.map(g=>`<div class="nav-group"><div class="nav-label">${g.group}</div>${g.items.map(([id,icon,label])=>`<button class="nav-item ${ui.page===id?'selected':''}" data-go="${id}"><span class="nav-icon">${icon}</span><span>${label}</span>${ui.page===id?'<i></i>':''}</button>`).join('')}</div>`).join('')}</nav><div class="sidebar-bottom"><span class="dot"></span>Hệ thống hỗ trợ quyết định <small>Phiên bản 4.2 · ${data.demo?'Dữ liệu mẫu':'Dữ liệu cục bộ'}</small></div></aside><div class="sidebar-shade ${ui.sidebar?'visible':''}" data-action="close-nav"></div><div class="workspace"><header class="topbar"><div class="top-left"><button class="mobile-toggle" data-action="toggle-nav" aria-label="Mở menu">☰</button><div class="breadcrumb">Không gian quản trị <span>›</span> <strong>${safe(titles[ui.page])}</strong></div></div><div class="top-right"><span class="scope">${data.demo?'● CHẾ ĐỘ DỮ LIỆU MẪU':'● DỮ LIỆU TRÌNH DUYỆT'}</span></div></header><main class="content"><div class="page-hero"><div class="hero-copy"><div class="eyebrow">SMART DECISION / ${safe(titles[ui.page].toUpperCase())}</div><h1>${safe(titles[ui.page])}</h1><p>${ui.page==='dashboard'?'Biến dữ liệu hoạt động thành thông tin, phương án và quyết định có căn cứ.':'Dữ liệu liên thông giúp ra quyết định có căn cứ'}</p></div><div class="hero-shape">✧</div></div>${ui.page!=='settings'?`<div class="content-toolbar"><div class="data-label"><span class="dot"></span> ${data.demo?'Đang xem dữ liệu minh họa':'Dữ liệu lưu tại trình duyệt này'} <small>· ${data.orders.length} đơn · ${data.products.length} sản phẩm</small></div>${['orders','products','suppliers','customers','inventory','decisions','finance'].includes(ui.page)?`<label class="search"><span>⌕</span><input id="page-search" value="${safe(ui.filter)}" placeholder="Tìm nhanh..." autocomplete="off" /></label>`:''}</div>`:''}<div class="page-content">${(pages[ui.page]||main)()}</div><footer>SmartDecision © 2026 · Công cụ hỗ trợ, không thay thế phán đoán quản lý · Dữ liệu cá nhân được lưu cục bộ</footer></main></div><button class="chat-fab ${ui.chatOpen?'active':''}" style="${ui.chatFabPos?`left:${Math.max(0,Math.min(innerWidth-200,ui.chatFabPos.x))}px;top:${Math.max(0,Math.min(innerHeight-65,ui.chatFabPos.y))}px;right:auto;bottom:auto;`:``}" data-action="toggle-chat" aria-label="Mở trợ lý phân tích"><span>✦</span><span>Trợ lý phân tích</span></button><div id="chat-slot">${chatHtml()}</div><div id="modal-slot"></div><div id="toast" class="toast" role="status" aria-live="polite"></div></div>`;const sidebarAfterRender=document.querySelector('.sidebar');if(sidebarAfterRender)sidebarAfterRender.scrollTop=sidebarScroll;if(typeof window.scrollTo==='function'&&previousScroll>0)window.scrollTo(0,previousScroll);}
function humanizeAi(text){
 let v=String(text||'').replace(/\\text\{([^{}]*)\}/g,'$1').replace(/\\times/g,' × ').replace(/\\cdot/g,' · ')
  .replace(/\\frac\{([^{}]+)\}\{([^{}]+)\}/g,'($1 / $2)')
  .replace(/\\\[|\\\]|\\\(|\\\)/g,'').replace(/\$\$/g,'').replace(/\\%/g,'%');
 return v.replace(/\\left|\\right/g,'').replace(/\\approx/g,'≈').replace(/\\leq/g,'≤').replace(/\\geq/g,'≥');
}
function renderAiMessage(text){
 const v=humanizeAi(text);
 return v.split(/\r?\n/).map(line=>{
  let t=safe(line).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
  const h=t.match(/^\s*#{1,4}\s+(.+)$/);if(h)return `<div class="ai-heading">${h[1]}</div>`;
  if(/^\s*(?:[-*•]|\d+[.)])\s+/.test(t))return `<div class="ai-item">${t.replace(/^\s*(?:[-*•]|\d+[.)])\s+/,'')} </div>`;
  return t?`<div class="ai-line">${t}</div>`:'<div class="ai-spacer"></div>';
 }).join('');
}
function chatHtml(){if(!ui.chatOpen)return '';const pos=ui.chatPos?`left:${Math.max(0,Math.min(innerWidth-310,ui.chatPos.x))}px;top:${Math.max(0,Math.min(innerHeight-240,ui.chatPos.y))}px;right:auto;bottom:auto;`:'';return `<div class="chat-panel" style="${pos}"><div class="chat-head" id="chat-handle"><span class="chat-logo">✦</span><div><strong>Trợ lý SmartDecision</strong><small>⠿ Giữ và kéo thanh này để di chuyển</small></div><button type="button" data-action="reset-chat-position" class="icon-button" aria-label="Đặt lại vị trí" title="Đặt lại vị trí">⤢</button><button type="button" data-action="toggle-chat" class="icon-button" aria-label="Đóng">✕</button></div><div class="chat-body" id="chat-body">${ui.chat.map(x=>`<div class="bubble ${x.role==='user'?'user':'assistant'}">${x.role==='user'?safe(x.text):renderAiMessage(x.text)}</div>`).join('')}${ui.chatBusy?'<div class="bubble assistant">Đang phân tích yêu cầu…</div>':''}</div><div class="chat-actionbar"><button type="button" data-action="chat-to-decision" class="chat-save-decision" title="Chỉ lưu đề xuất sau khi bạn xác nhận">＋ Lưu phân tích thành đề xuất</button></div><div class="prompt-chips"><button data-chat-prompt="Phân tích doanh thu và giới hạn của dữ liệu">Doanh thu</button><button data-chat-prompt="Các sản phẩm cần nhập kho ưu tiên">Cảnh báo kho</button><button data-chat-prompt="Gợi ý phương án cải thiện lợi nhuận">Quyết định</button></div><form id="chat-form" class="chat-form"><input name="question" placeholder="Hỏi về hoạt động kinh doanh..." value="${safe(ui.chatInput)}" ${ui.chatBusy?'disabled':''} required><button type="button" class="chat-mic" data-action="mic" aria-label="Nhập bằng giọng nói" title="Nói bằng giọng nói"><svg viewBox="0 0 24 24" aria-hidden="true" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-4 0h8"/></svg></button><button type="submit" ${ui.chatBusy?'disabled':''} aria-label="Gửi">➜</button></form></div>`;}
function modal(title,inner,id){document.getElementById('modal-slot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-title"><h2>${safe(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">✕</button></div><form id="${id}" class="modal-form">${inner}<div class="modal-actions"><button type="button" data-action="close-modal" class="btn secondary">Hủy</button><button type="submit" class="btn primary">Lưu thông tin</button></div></form></section></div>`;}
const input=(name,label,value='',type='text',required=true,extra='')=>`<label>${safe(label)}<input name="${name}" type="${type}" value="${safe(value)}" ${required?'required':''} ${extra} /></label>`;
const select=(name,label,options,value='',required=true)=>`<label>${safe(label)}<select name="${name}" ${required?'required':''}>${options.map(([k,t])=>`<option value="${safe(k)}" ${value===k?'selected':''}>${safe(t)}</option>`).join('')}</select></label>`;
const categories=()=>[...new Set(data.products.map(p=>String(p.category||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));
function categoryControl(p){const current=p?.category||'',options=categories();const selected=current&&!options.includes(current)?'__new__':current||options[0]||'__new__';
 const entries=[...options.map(z=>[z,z]),['__new__','＋ Thêm danh mục mới']];
 return `<div class="category-control">${select('categoryChoice','Danh mục sản phẩm',entries,selected)}<label class="category-new" ${selected==='__new__'?'':'hidden'}>Tên danh mục mới<input name="newCategory" placeholder="Ví dụ: Văn phòng phẩm" maxlength="80" value="${selected==='__new__'?safe(current):''}" ${selected==='__new__'?'required':''}></label></div>`;
}
const pOpts=(blank=false)=>[...(blank?[['','Chọn sản phẩm']]:[]),...data.products.map(p=>[p.id,`${p.name} (còn ${p.stock})`])];
const supOpts=(blank=false)=>[...(blank?[['','Chọn nhà cung cấp']]:[]),...data.suppliers.map(s=>[s.id,s.name])];
const expenseCategories=()=>[...new Set(['Vận hành','Marketing','Logistics','Nhân sự','Điện nước',...data.expenses.map(e=>String(e.category||'').trim())].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));
function expenseCategoryControl(e){const category=e?.category||'Vận hành';const options=expenseCategories();return `<div class="expense-category-control">${select('expenseCategoryChoice','Nhóm chi phí',[...options.map(x=>[x,x]),['__new__','＋ Thêm nhóm chi phí mới']],category)}<label class="expense-category-new" hidden>Tên nhóm mới<input name="newExpenseCategory" maxlength="70" placeholder="Ví dụ: Bảo trì" /></label></div>`;}
const customersOpts=()=>[['','Chọn khách hàng'],...data.customers.map(c=>[c.id,`${c.name}${c.phone?' · '+c.phone:''}`])];
function orderLine(){return `<div class="order-line">${select('productId','Sản phẩm',pOpts(true))}${input('quantity','Số lượng','1','number',true,'min="1" step="1"')}<button type="button" data-action="remove-line" class="icon-button line-remove" aria-label="Xóa dòng">✕</button></div>`;}
// Supporting receipts are stored as original browser-local files in IndexedDB, not in localStorage.
// No upload to third-party servers. Evidence is NOT proof of payment by itself.
function evidenceDatabase(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(Error('Trình duyệt không hỗ trợ lưu chứng từ.'));const r=indexedDB.open('smartdecision_evidence_v1',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('attachments'))r.result.createObjectStore('attachments',{keyPath:'ref'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function storeEvidence(ref,file){if(!file||!file.size)return;const mime=file.type;
 if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(mime))throw Error('Chỉ hỗ trợ ảnh JPG, PNG, WebP hoặc PDF.');
 if(file.size>6*1024*1024)throw Error('Chứng từ tối đa 6 MB.');
 const db=await evidenceDatabase();try{await new Promise((resolve,reject)=>{const tx=db.transaction('attachments','readwrite');tx.objectStore('attachments').put({ref,name:file.name,mime,blob:file,date:new Date().toISOString()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
async function readEvidence(ref){const db=await evidenceDatabase();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('attachments','readonly');const q=tx.objectStore('attachments').get(ref);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}finally{db.close();}}
async function showEvidence(ref){try{const record=await readEvidence(ref);if(!record)return notice('Chưa có chứng từ đính kèm cho giao dịch này.','bad');const u=URL.createObjectURL(record.blob);const inner=record.mime==='application/pdf'?`<iframe src="${u}" title="Chứng từ PDF" class="evidence-frame"></iframe>`:`<img src="${u}" alt="Ảnh chứng từ đã tải lên" class="evidence-image">`;
 document.getElementById('modal-slot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal evidence-modal" role="dialog" aria-modal="true"><div class="modal-title"><h2>${safe(record.name)}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">✕</button></div><div class="evidence-content">${inner}<p>Chứng từ do người dùng cung cấp, hệ thống chưa xác minh tính hợp lệ.</p><a href="${u}" download="${safe(record.name)}" class="btn primary">↓ Tải chứng từ</a></div></section></div>`;
 }catch(err){notice(err.message||'Không thể mở chứng từ.','bad');}}
function evidenceField(label='Đính kèm chứng từ (không bắt buộc)'){return `<label>${safe(label)}<input name="evidence" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" /><small class="field-help">Ảnh JPG, PNG, WebP hoặc PDF đến 6 MB. Chỉ lưu trong trình duyệt này, không gửi cho AI.</small></label>`;}
async function exportEvidence(){let db;try{db=await evidenceDatabase();return await new Promise((resolve,reject)=>{const tx=db.transaction('attachments','readonly'),request=tx.objectStore('attachments').getAll();request.onsuccess=async()=>{try{const result=[];for(const record of request.result){if(!record.blob||!record.mime)continue;const b64=await new Promise((yes,no)=>{const fr=new FileReader();fr.onload=()=>yes(fr.result);fr.onerror=()=>no(fr.error);fr.readAsDataURL(record.blob);});result.push({ref:record.ref,name:record.name,mime:record.mime,dataUrl:b64,date:record.date});}resolve(result);}catch(e){reject(e);}};request.onerror=()=>reject(request.error);});}catch(err){console.warn('Chứng từ không thể xuất',err);return [];}finally{db?.close();}}
async function backupAll(){try{const evidence=await exportEvidence();const pack={schema:'smartdecision-v3',exportedAt:new Date().toISOString(),data,evidence};const text=JSON.stringify(pack,null,2);if(text.length>65*1024*1024)return notice('Bản sao lưu quá lớn (trên 65 MB). Hãy giảm số chứng từ hoặc lưu chứng từ ra từng tệp.','bad');download('smartdecision-sao-luu-day-du.json',text,'application/json');}catch(err){notice('Không xuất được bản sao lưu: '+err.message,'bad');}}
async function restoreEvidence(records){if(!Array.isArray(records))return 0;if(records.length>500)throw Error('Bản sao lưu có quá nhiều chứng từ.');let count=0;for(const rec of records){if(!rec||typeof rec.ref!=='string'||!/^(purchase|payment):[\w-]{1,90}$/.test(rec.ref)||typeof rec.dataUrl!=='string')continue;if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(rec.mime))continue;const b64=rec.dataUrl.split(',')[1]||'';if(b64.length>9*1024*1024)continue;const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const file=new File([bytes],String(rec.name||'Chứng từ').slice(0,150),{type:rec.mime});await storeEvidence(rec.ref,file);count++;}return count;}
async function commitEvidence(ref,file){if(!file?.size)return;try{await storeEvidence(ref,file);notice('Đã lưu chứng từ tại trình duyệt này.');}catch(e){notice(`Giao dịch đã lưu nhưng chứng từ chưa lưu được: ${e.message}`,'bad');}}
function openModal(kind,id=''){ui.editing=id;const p=data.products.find(x=>x.id===id),e=data.expenses.find(x=>x.id===id),d=data.decisions.find(x=>x.id===id),sup=data.suppliers.find(x=>x.id===id);switch(kind){case'new-order':modal('Tạo đơn hàng liên kết kho',`${select('customerId','Khách hàng',customersOpts())}<div class="order-line-items" id="order-lines">${orderLine()}</div><button type="button" data-action="add-line" class="btn secondary">＋ Thêm dòng sản phẩm</button>${select('status','Trạng thái ban đầu',[['Đang xử lý','Đang xử lý'],['Hoàn thành','Hoàn thành'],['Đã hủy','Đã hủy']])}<p class="caption">Hoàn thành sẽ trừ tồn kho đúng một lần. Hệ thống tự lưu giá bán và giá vốn tại thời điểm tạo đơn.</p>`,'new-order-form');break;case'new-product':case'edit-product':modal(p?'Sửa danh mục sản phẩm':'Thêm sản phẩm',`${input('sku','Mã SKU',p?.sku||'')}${input('name','Tên sản phẩm',p?.name||'')}${categoryControl(p)}${input('price','Giá bán (₫)',p?.price??'0','number',true,'min="0" step="1"')}${input('min','Ngưỡng cảnh báo tồn',p?.min??'5','number',true,'min="0" step="1"')}${select('supplierId','Nhà cung cấp mặc định',[['','Chưa chọn'],...supOpts()],p?.supplierId||'',false)}${p?select('active','Trạng thái',[['yes','Đang bán'],['no','Ngừng bán']],p.active===false?'no':'yes'):''}<p class="caption">Không phải nhập giá vốn ở đây. Giá vốn được tự tính từ phiếu nhập (giá mua + phí nhập kho); hàng mới có tồn 0 cho đến khi nhập.</p>`,'product-form');break;case'new-supplier':case'edit-supplier':modal(sup?'Sửa nhà cung cấp':'Thêm nhà cung cấp',input('name','Tên nhà cung cấp',sup?.name||'')+input('phone','Số điện thoại',sup?.phone||'', 'tel',false)+input('contact','Người liên hệ',sup?.contact||'', 'text',false),'supplier-form');break;case'new-customer':case'edit-customer':{const c=data.customers.find(x=>x.id===id);modal(c?'Sửa khách hàng':'Thêm khách hàng',input('name','Tên khách hàng',c?.name||'')+input('phone','Điện thoại',c?.phone||'', 'tel',false)+input('email','Email',c?.email||'', 'email',false),'customer-form');break;}case'receive':{
 const selectedSupplier=ui.prefillSupplier||p?.supplierId||'',selectedProduct=p?.id||'';
 const last=data.purchases.find(x=>x.productId===selectedProduct);
 const suggestedPrice=last?.unitCost??p?.lastPurchasePrice??0;
 ui.prefillSupplier='';
 modal('Phiếu nhập hàng & công nợ',`${select('supplierId','Nhà cung cấp',[['','Chọn nhà cung cấp'],...supOpts()],selectedSupplier)}${select('productId','Sản phẩm',pOpts(true),selectedProduct)}${input('quantity','Số lượng nhập','1','number',true,'min="1" step="1"')}${input('unitCost','Đơn giá mua từ nhà cung cấp (₫)',suggestedPrice,'number',true,'min="0" step="1"')}${input('freight','Phí vận chuyển hàng về kho (₫)','0','number',true,'min="0" step="1"')}${input('handling','Chi phí bốc xếp liên quan (₫)','0','number',true,'min="0" step="1"')}${select('feesBilledBySupplier','Đơn vị thu phí nhập kho',[['no','Đơn vị vận chuyển / dịch vụ (đã thanh toán)'],['yes','Nhà cung cấp thu (tính vào công nợ NCC)']],'no')}<div id="purchase-preview" class="purchase-preview" aria-live="polite"></div>${input('paid','Đã trả cho nhà cung cấp (₫)','0','number',true,'min="0" step="1"')}${evidenceField('Ảnh hóa đơn / phiếu giao hàng (tùy chọn)')}<p class="caption">Giá vốn nhập kho = tiền mua + phí đưa hàng về kho. Phí do bên ngoài thu được giả định thanh toán ngay; không ghi trùng vào công nợ nhà cung cấp.</p>`,'receive-form');
 updatePurchasePreview();break;}
case'pay':modal('Thanh toán công nợ',`${select('purchaseId','Phiếu mua còn nợ',[['','Chọn phiếu mua'],...data.purchases.filter(p=>p.total>p.paid).map(p=>[p.id,`${p.id} · ${supplierName(p.supplierId)} · còn ${money(p.total-p.paid)}`])])}${input('amount','Số tiền thanh toán (₫)','1','number',true,'min="1" step="1"')}${evidenceField('Ảnh chứng từ thanh toán (tùy chọn)')}`,'pay-form');break;case'audit':modal('Kiểm kê tồn kho',`${select('productId','Sản phẩm',pOpts(true))}${input('actual','Tồn thực tế','0','number',true,'min="0" step="1"')}<label>Lý do điều chỉnh<textarea name="reason" required minlength="3" rows="3" placeholder="Ghi rõ kết quả kiểm đếm hoặc nguyên nhân..." ></textarea></label>`,'audit-form');break;case'new-expense':case'edit-expense':modal(e?'Sửa khoản chi':'Ghi khoản chi',`${input('name','Nội dung khoản chi',e?.name||'')}${expenseCategoryControl(e)}${input('amount','Số tiền (₫)',e?.amount||'','number',true,'min="1" step="1"')}${input('date','Ngày chi',e?.date||isoDay(new Date()),'date')}`,'expense-form');break;case'new-decision':case'edit-decision':modal(d?'Cập nhật quyết định':'Tạo hồ sơ quyết định',`${input('title','Tên quyết định',d?.title||'')}${input('reason','Căn cứ / lý do',d?.reason||'','text',true)}${input('owner','Người phụ trách',d?.owner||'Quản lý')}${input('due','Hạn hoàn thành',d?.due||isoDay(new Date()),'date',false)}${input('expected','Kết quả kỳ vọng',d?.expected||'','text',false)}${input('actual','Kết quả thực tế',d?.actual||'','text',false)}${select('status','Trạng thái',[['Đề xuất','Đề xuất'],['Đã duyệt','Đã duyệt'],['Đang thực hiện','Đang thực hiện'],['Hoàn thành','Hoàn thành'],['Hủy','Hủy']],d?.status||'Đề xuất')}`,'decision-form');break;case'rate-supplier':modal(`Chấm điểm · ${sup?.name||''}`,`${input('price','Giá cả (1–5)',data.ratings[id]?.price||3,'number',true,'min="1" max="5" step="1"')}${input('delivery','Giao hàng (1–5)',data.ratings[id]?.delivery||3,'number',true,'min="1" max="5" step="1"')}${input('quality','Chất lượng (1–5)',data.ratings[id]?.quality||3,'number',true,'min="1" max="5" step="1"')}<p class="caption">Điểm do người quản lý tự đánh giá, không phải đo lường khách quan từ hệ thống.</p>`,'rate-form');break;default:return;}
ui.modal=kind;document.querySelector('.modal input, .modal select')?.focus();}
function updatePurchasePreview(){const f=document.getElementById('receive-form');if(!f)return;
 const fd=new FormData(f),q=Number(fd.get('quantity')||0),price=Number(fd.get('unitCost')||0),freight=Number(fd.get('freight')||0),handling=Number(fd.get('handling')||0);
 const landed=q*price+freight+handling,billed=fd.get('feesBilledBySupplier')==='yes',owed=q*price+(billed?freight+handling:0);
 const node=document.getElementById('purchase-preview');if(!node)return;
 const valid=[q,price,freight,handling].every(x=>Number.isFinite(x)&&x>=0)&&q>0;
 node.innerHTML=valid?`<div><small>Giá vốn nhập kho / đơn vị</small><strong>${money(landed/q)}</strong></div><div><small>Giá trị nhập kho</small><strong>${money(landed)}</strong></div><div><small>Phải trả nhà cung cấp</small><strong>${money(owed)}</strong></div>`:'<span class="muted">Nhập số lượng và giá mua để xem chi phí tự tính.</span>';
}
function closeModal(){ui.modal='';ui.editing='';document.getElementById('modal-slot').innerHTML='';}
function action(act,id){switch(act){case 'view-evidence':void showEvidence(id);break;case 'toggle-nav':ui.sidebar=!ui.sidebar;render();break;case 'close-nav':ui.sidebar=false;render();break;case 'close-modal':closeModal();break;case 'toggle-chat':ui.chatOpen=!ui.chatOpen;render();scrollChat();break;case 'add-line':document.getElementById('order-lines')?.insertAdjacentHTML('beforeend',orderLine());break;case 'remove-line':{const all=document.querySelectorAll('.order-line');if(all.length>1)event.target.closest('.order-line')?.remove();break;}case 'delete-expense':if(confirm('Xóa khoản chi này? Đây là thay đổi dữ liệu tài chính.'))transactional(s=>expenseDelete(s,id),'Đã xóa khoản chi.');break;case 'finance-ai':sendChat('Phân tích tình hình doanh thu, chi phí vận hành, dòng tiền trả nhà cung cấp, công nợ và lợi nhuận. Phân biệt dòng tiền với chi phí giá vốn, đưa ra tối đa 3 khuyến nghị có số liệu và rủi ro.');break;case 'go-finance':go('finance');break;case 'rank-to-decision':{const r=scoreSuppliers(data);if(!r.length)return;transactional(s=>decisionSave(s,{title:`Đánh giá chọn nhà cung cấp ${r[0].name}`,reason:`Xếp hạng đa tiêu chí: ${r[0].score.toFixed(2)}/5 (giá ${data.weights.price}, giao ${data.weights.delivery}, chất lượng ${data.weights.quality}). Điểm do người dùng nhập; cần xác minh thực tế.`,expected:'Xác minh chất lượng, giá và thời gian giao trước khi ký mua.',owner:'Quản lý mua hàng'}),'Đã lưu phương án vào quản lý quyết định.');go('decisions');break;}case 'suggest-replenishment':{const p=data.products.find(x=>x.id===id);if(!p)return;const q=Math.max(0,p.min-p.stock);transactional(s=>decisionSave(s,{title:`Đề xuất nhập bổ sung ${p.name}`,reason:`Tồn ${p.stock}, ngưỡng ${p.min}; số lượng tối thiểu để trở lại ngưỡng: ${q}. Ước vốn ${money(q*p.cost)}, chưa phải báo giá thực tế.`,expected:`Nâng tồn kho tới ngưỡng ${p.min}.`,owner:'Quản lý kho'}),'Đã lưu đề xuất, chưa tạo phiếu nhập tự động.');go('decisions');break;}case 'export-report':{const f=financials(data,ui.month);download('smartdecision-bao-cao.csv','\ufeffChỉ tiêu,Giá trị\n'+[['Doanh thu',f.revenue],['Giá vốn đã biết',f.cogsKnown],['Chi phí vận hành',f.expenses],['Lợi nhuận',f.net===null?'Thiếu dữ liệu':f.net],['Đơn thiếu giá vốn',f.missing.length],['Giá trị tồn kho',inventoryValue(data)],['Đã chi nhà cung cấp',procurementSummary(data,ui.month).paidSupplier],['Đã chi phí nhập kho bên ngoài',procurementSummary(data,ui.month).paidExternal],['Tổng chi đã ghi nhận (mua hàng và hoạt động)',procurementSummary(data,ui.month).paidSupplier+procurementSummary(data,ui.month).paidExternal+f.expenses],['Công nợ',data.suppliers.reduce((z,x)=>z+supplierDebt(data,x.id),0)]].map(([k,v])=>`"${k}","${v}"`).join('\n'),'text/csv;charset=utf-8');break;}case 'backup':void backupAll();break;case 'restore':document.getElementById('restore-file')?.click();break;case 'migrate':if(confirm('Bạn muốn chuyển dữ liệu SmartDecision cũ trong cùng trình duyệt? Hãy xuất bản sao lưu v3 trước. Dữ liệu hiện tại sẽ được thay thế.')){try{setData(migrateLegacy(localStorage),'Đã chuyển dữ liệu cũ. Các đơn thiếu giá vốn sẽ được đánh dấu chưa xác minh.');}catch(e){notice(e.message,'bad');}}break;case 'reset-demo':if(confirm('Thay thế toàn bộ dữ liệu hiện tại bằng dữ liệu minh họa? Hãy xuất sao lưu trước.')){setData(seedDemo(),'Đã tạo dữ liệu mẫu mới.');}break;case 'reset-empty':if(confirm('Xóa toàn bộ dữ liệu phiên bản 3 trên trình duyệt này? Không thể hoàn tác nếu chưa sao lưu.')){if(confirm('Xác nhận lần cuối: bắt đầu bằng dữ liệu trống?'))setData(baseState(),'Đã bắt đầu với dữ liệu trống.');}break;case 'go-alerts':go('alerts');break;
 case 'go-purchase':go('suppliers');break;
 case 'go-ranking':go('ranking');break;
 case 'go-payment':go('suppliers');openModal('pay');break;
 case 'buy-product':go('suppliers');openModal('receive',id);break;
 case 'forecast-to-decision':{const p=data.products.find(x=>x.id===id),f=p?forecast(data,id):null;if(!p||!f)return notice('Chưa có dữ liệu đủ để tạo quyết định từ dự báo.','bad');const q=Math.max(0,f.next30+p.min-p.stock);if(transactional(z=>decisionSave(z,{title:`Dự báo: nhập ${q} ${p.name}`,reason:`Bán ${f.units} sản phẩm trong kỳ; dự báo nhu cầu 30 ngày tới ${f.next30}; tồn ${p.stock}, ngưỡng ${p.min}. Số cần cân nhắc nhập = ${q}. Mô hình tốc độ bán; không tính mùa vụ.`,owner:'Quản lý mua hàng',expected:`Kiểm tra báo giá và thời gian giao, sau đó cân nhắc nhập ${q} sản phẩm.`}),'Đã lưu quyết định dựa trên dự báo.'))go('decisions');break;}
 case 'scenario-to-decision':{const sc=scenario(data,ui.scenario,ui.month);if(!sc)return notice('Chưa đủ dữ liệu giá vốn để lưu mô phỏng.','bad');const x=ui.scenario;if(transactional(z=>decisionSave(z,{title:'Mô phỏng cải thiện lợi nhuận',reason:`Cơ sở ${money(sc.baseNet)}; giả định giá bán ${x.pricePct}%, số lượng ${x.unitsPct}%, giá vốn ${x.costPct}%, chi phí ${x.expensesPct}%. Lợi nhuận giả định ${money(sc.net)}, chênh ${money(sc.change)}. Đây không phải dự báo chắc chắn.`,owner:'Quản lý kinh doanh',expected:`Đánh giá biến động lợi nhuận ${money(sc.change)} so với cơ sở.`}),'Đã lưu phương án vào vòng đời quyết định.'))go('decisions');break;}
 case 'buy-from-supplier':ui.prefillSupplier=id;go('suppliers');openModal('receive');break;
 case 'reset-chat-position':ui.chatPos=null;ui.chatFabPos=null;try{localStorage.removeItem('smartdecision_v3_chatpos');localStorage.removeItem('smartdecision_v4_chatfabpos');}catch{}render();break;
 case 'chat-to-decision':{const reply=[...ui.chat].reverse().find(m=>m.role==='assistant');if(!reply)return notice('Chưa có phân tích để lưu.','bad');if(!confirm('Lưu nội dung phân tích thành đề xuất để bạn xét duyệt? Chưa thực hiện bất kỳ giao dịch nào.'))return;const lastQuestion=[...ui.chat].reverse().find(m=>m.role==='user')?.text||'Đề xuất từ trợ lý';if(transactional(z=>decisionSave(z,{title:lastQuestion.slice(0,110),reason:reply.text.slice(0,1800),owner:'Quản lý',expected:'Kiểm tra tính khả thi trước khi phê duyệt và thực hiện.'}),'Đã lưu phân tích thành đề xuất, chưa thay đổi nghiệp vụ.'))go('decisions');break;}case 'mic':voice();break;default:openModal(act,id);}}
function go(page){if(!pages[page]||page===ui.page)return;
 // Only switch the content. Preserve the user's current sidebar and viewport scroll
 // rather than restoring a stale scroll position from a previous visit to this page.
 ui.page=page;ui.filter='';ui.sidebar=false;render();
}
function download(filename,text,mime){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Đã tạo tệp tải xuống.');}
function submitForm(f){lastMutationOk=true;const fields=Object.fromEntries(new FormData(f).entries()),a=f.id;switch(a){case 'new-order-form':{const fd=new FormData(f);const ids=fd.getAll('productId'),quant=fd.getAll('quantity');transactional(s=>createOrder(s,{customerId:fields.customerId,status:fields.status,lines:ids.map((productId,i)=>({productId,quantity:quant[i]}))}),'Đã tạo đơn hàng và cập nhật kho khi hoàn thành.');break;}case 'product-form':{const category=fields.categoryChoice==='__new__'?String(fields.newCategory||'').trim():fields.categoryChoice;
 if(!category){notice('Vui lòng chọn hoặc nhập danh mục sản phẩm.','bad');return;}
 const item={...fields,category,active:fields.active==='yes'};
 transactional(s=>ui.editing?productEdit(s,ui.editing,item):productCreate(s,item),'Đã lưu danh mục sản phẩm.');break;}case 'supplier-form':transactional(s=>ui.editing?supplierEdit(s,ui.editing,fields):supplierCreate(s,fields),'Đã lưu nhà cung cấp.');break;case 'customer-form':transactional(s=>ui.editing?customerEdit(s,ui.editing,fields):customerCreate(s,fields),'Đã lưu khách hàng.');break;case 'receive-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Chứng từ cần là ảnh/PDF tối đa 6 MB.','bad');if(transactional(s=>receiveStock(s,fields),'Đã nhập kho và tính công nợ từ phiếu mua.'))void commitEvidence('purchase:'+data.purchases[0].id,file);break;}case 'pay-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Chứng từ cần là ảnh/PDF tối đa 6 MB.','bad');if(transactional(s=>payPurchase(s,fields),'Đã ghi thanh toán và cập nhật công nợ.')){const purchase=data.purchases.find(x=>x.id===fields.purchaseId),last=purchase?.payments?.at(-1);if(last)void commitEvidence('payment:'+last.id,file);}break;}case 'audit-form':transactional(s=>auditStock(s,fields),'Đã ghi biên bản kiểm kê và nhật ký kho.');break;case 'expense-form':{const category=fields.expenseCategoryChoice==='__new__'?String(fields.newExpenseCategory||'').trim():(fields.expenseCategoryChoice||fields.category);if(!category)return notice('Vui lòng nhập tên nhóm chi phí mới.','bad');transactional(s=>expenseSave(s,{...fields,category,id:ui.editing||undefined}),'Đã ghi nhận chi phí và cập nhật báo cáo.');break;}case 'decision-form':transactional(s=>decisionSave(s,{...fields,id:ui.editing||undefined}),'Đã lưu quyết định.');break;case 'rate-form':{const scores={price:Number(fields.price),delivery:Number(fields.delivery),quality:Number(fields.quality)};if(Object.values(scores).some(z=>!Number.isInteger(z)||z<1||z>5))return notice('Điểm phải nằm trong khoảng 1–5.','bad');const s=structuredClone(data);s.ratings[ui.editing]=scores;setData(s,'Đã cập nhật đánh giá nhà cung cấp.');break;}case 'settings-form':{if(!fields.name.trim())return notice('Cần nhập tên doanh nghiệp.','bad');const s=structuredClone(data);s.company={...s.company,...fields};setData(s,'Đã lưu tên và thông tin doanh nghiệp.');return;}case 'weights-form':{const w={price:Number(fields.price),delivery:Number(fields.delivery),quality:Number(fields.quality)};if(Object.values(w).some(z=>!Number.isSafeInteger(z)||z<0||z>100)||Object.values(w).every(z=>z===0))return notice('Trọng số hợp lệ 0–100 và có ít nhất một trọng số dương.','bad');const s=structuredClone(data);s.weights=w;setData(s,'Đã cập nhật trọng số đánh giá.');return;}case 'scenario-form':{const x=Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,Number(v)]));if(Object.values(x).some(z=>!Number.isFinite(z))||x.unitsPct < -100||x.pricePct < -80||x.costPct < -80||x.expensesPct < -100)return notice('Giả định không hợp lệ.','bad');ui.scenario=x;render();return;}case 'goal-form':{if(!Number.isFinite(Number(fields.goal))||Number(fields.goal)<0)return notice('Mục tiêu không hợp lệ.','bad');ui.goal=Number(fields.goal);render();return;}case 'chat-form':ui.chatInput='';sendChat(fields.question);return;default:return;}if(ui.modal&&lastMutationOk)closeModal();}
function localDss(question){const a=simpleRecommendation(data),q=String(question||'').toLowerCase();let lines=['Phân tích dữ liệu tại cửa hàng:'];if(/kho|nhập|tồn|hàng/.test(q)){lines.push(`• ${a.low.length} sản phẩm chạm ngưỡng cảnh báo.`);for(const p of a.low.slice(0,5))lines.push(`• ${p.name}: còn ${p.stock}, ngưỡng ${p.min}, thiếu tối thiểu ${Math.max(0,p.min-p.stock)} đơn vị.`);lines.push('Khuyến nghị có điều kiện: kiểm tra nhu cầu dự kiến và báo giá NCC trước khi duyệt phiếu nhập.');}else if(/công nợ|nhà cung cấp|thanh toán/.test(q)){lines.push(`• Tổng công nợ từ phiếu mua: ${money(a.debts.reduce((z,x)=>z+x.debt,0))}.`);a.debts.slice(0,4).forEach(x=>lines.push(`• ${x.name}: ${money(x.debt)}.`));lines.push('Thanh toán nợ làm giảm phải trả, không làm giảm lợi nhuận thêm lần nữa.');}else{lines.push(`• Doanh thu đơn hoàn thành: ${money(a.revenue)}.`);lines.push(`• Chi phí hoạt động: ${money(a.expense)}.`);lines.push(`• Lợi nhuận trước thuế: ${a.profit===null?'chưa xác minh do đơn thiếu giá vốn':money(a.profit)}.`);lines.push(`• ${a.low.length} SKU cần chú ý tồn kho; ${a.unverified} đơn thiếu giá vốn.`);lines.push('Để quyết định: vào Mô phỏng phương án so sánh các giả định, rồi lưu quyết định và theo dõi kết quả.');}return lines.join('\n');}
async function sendChat(question){const q=String(question||'').trim();if(!q||ui.chatBusy)return;ui.chatOpen=true;ui.chat.push({role:'user',text:q});ui.chatBusy=true;render();scrollChat();const f=financials(data);const context={company:{sector:data.company.sector},products:data.products.map(p=>({sku:p.sku,name:p.name,stock:p.stock,min:p.min,price:p.price,cost:p.cost})).slice(0,100),finance:{revenue:f.revenue,verifiedCogs:f.cogsKnown,operatingExpenses:f.expenses,profit:f.net,missingCostOrders:f.missing.length,cashPaidSupplier:procurementSummary(data).paidSupplier,cashPaidFreight:procurementSummary(data).paidExternal,recordedCashOutflow:f.expenses+procurementSummary(data).paidSupplier+procurementSummary(data).paidExternal},lowStock:simpleRecommendation(data).low.map(p=>({name:p.name,stock:p.stock,min:p.min})),supplierDebts:data.suppliers.map(s=>({supplier:s.name,payable:supplierDebt(data,s.id)})),decisionCount:data.decisions.length,limitations:'Dữ liệu cục bộ; một số đơn lịch sử thiếu giá vốn. Không suy đoán dữ liệu thiếu. Không có thông tin nhận dạng khách hàng.'};try{const response=await fetch('/.netlify/functions/decision-ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,context,history:ui.chat.slice(-6).map(m=>({role:m.role,content:m.text}))})});const result=await response.json().catch(()=>({}));if(!response.ok)throw Error(result.error||`HTTP ${response.status}`);ui.chat.push({role:'assistant',text:result.answer||'Gemini chưa tạo được câu trả lời.',source:'gemini'});}catch(e){ui.chat.push({role:'assistant',text:`Gemini đang tạm gián đoạn. Dưới đây là kết quả tính trực tiếp từ dữ liệu hệ thống:\n\n${localDss(q)}`,source:'local'});}finally{ui.chatBusy=false;render();scrollChat();}}
function scrollChat(){requestAnimationFrame(()=>{const el=document.getElementById('chat-body');if(el)el.scrollTop=el.scrollHeight;});}
function voice(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!window.isSecureContext)return notice('Micro cần HTTPS.','bad');if(!Speech)return notice('Trình duyệt chưa hỗ trợ nhận dạng giọng nói.','bad');const r=new Speech();r.lang='vi-VN';r.onresult=e=>{const t=e.results?.[0]?.[0]?.transcript||'';const x=document.querySelector('#chat-form input');if(x)x.value=(x.value?x.value+' ':'')+t;};r.onerror=e=>notice(`Micro: ${e.error}`,'bad');r.start();notice('Đang nghe giọng nói tiếng Việt…');}
// Single document event delegation, avoiding inline script / onClick injection.
document.addEventListener('click',e=>{const goEl=e.target.closest('[data-go]');if(goEl){go(goEl.dataset.go);return;}const ch=e.target.closest('[data-chat-prompt]');if(ch){sendChat(ch.dataset.chatPrompt);return;}const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='close-modal'&&e.target.closest('.modal')&&e.target===b.closest('.modal-backdrop'))return;if(b.classList.contains('modal-backdrop')&&e.target!==b)return;const name=b.dataset.action;if(name==='toggle-chat'&&b.classList.contains('chat-fab')&&ignoreFabClick){ignoreFabClick=false;return;}if(name==='remove-line'){const all=document.querySelectorAll('.order-line');if(all.length>1)b.closest('.order-line')?.remove();return;}action(name,b.dataset.id||'');});
document.addEventListener('submit',e=>{e.preventDefault();try{submitForm(e.target);}catch(err){notice(err.message||'Có lỗi xử lý dữ liệu.','bad');}});
document.addEventListener('change',e=>{const x=e.target;
 if(x.name==='expenseCategoryChoice'){const f=x.closest('.expense-category-control')?.querySelector('.expense-category-new'),inp=f?.querySelector('input');if(f){f.hidden=x.value!=='__new__';if(inp){inp.required=x.value==='__new__';if(x.value==='__new__')inp.focus();}}return;}
 if(x.name==='categoryChoice'){const wrap=x.closest('.category-control');const field=wrap?.querySelector('.category-new'),inp=field?.querySelector('input');if(field){field.hidden=x.value!=='__new__';if(inp){inp.required=x.value==='__new__';if(x.value==='__new__')inp.focus();}}return;}
 if(x.name==='productId'&&x.closest?.('#receive-form')){const p=data.products.find(v=>v.id===x.value),recent=data.purchases.find(v=>v.productId===x.value);const f=x.closest('form');if(f){const cost=f.querySelector('[name="unitCost"]');if(cost)cost.value=recent?.unitCost??p?.lastPurchasePrice??0;const supplier=f.querySelector('[name="supplierId"]');if(supplier&&p?.supplierId)supplier.value=p.supplierId;}updatePurchasePreview();return;}
 if(x.closest?.('#receive-form'))updatePurchasePreview();
 if(x.matches('[data-order-status]')){const id=x.dataset.orderStatus;const order=data.orders.find(o=>o.id===id);if(!order)return;transactional(s=>updateOrderStatus(s,id,x.value),'Đã cập nhật trạng thái đơn và tồn kho liên quan.');if(data.orders.find(o=>o.id===id)?.status!==x.value)render();}else if(x.matches('[data-forecast-product]')){ui.forecastProduct=x.value;render();}else if(x.matches('[data-filter-month]')){ui.month=x.value;render();}else if(x.id==='restore-file'){const f=x.files?.[0];if(!f)return;if(f.size>65_000_000)return notice('Tệp sao lưu quá lớn (tối đa 65 MB).','bad');f.text().then(text=>{const pack=JSON.parse(text);const v=pack.schema==='smartdecision-local-v1'?migrateLegacyBackup(pack):validateData(pack.schema==='smartdecision-v3'?pack.data:pack);if(!confirm('Khôi phục sẽ thay thế dữ liệu hiện tại. Bạn đã sao lưu chưa?'))return;setData(v,'Đã khôi phục bản sao lưu dữ liệu.');if(Array.isArray(pack.evidence)&&pack.evidence.length)restoreEvidence(pack.evidence).then(n=>notice(`Đã nhập thêm ${n} chứng từ.`)).catch(err=>notice('Dữ liệu đã khôi phục nhưng chứng từ có lỗi: '+err.message,'bad'));}).catch(err=>notice(`Không thể nhập dữ liệu: ${err.message}`,'bad'));}});
document.addEventListener('input',e=>{if(e.target.closest?.('#receive-form'))updatePurchasePreview();if(e.target.id==='page-search'){const old=e.target.selectionStart;ui.filter=e.target.value;const sc=window.scrollY;render();const x=document.getElementById('page-search');if(x){x.focus();x.setSelectionRange(old,old);}window.scrollTo(0,sc);}});
// Prevent number wheel changes on focused fields.
document.addEventListener('wheel',e=>{if(e.target.matches?.('input[type="number"]')&&document.activeElement===e.target)e.preventDefault();},{passive:false});
let dragging=null;let ignoreFabClick=false;
document.addEventListener('pointerdown',e=>{
 const handle=e.target.closest?.('#chat-handle');const fab=e.target.closest?.('.chat-fab');
 if((!handle&&!fab)||(handle&&e.target.closest?.('button')))return;
 const node=(handle||fab).closest(handle?'.chat-panel':'.chat-fab');if(!node)return;
 const r=node.getBoundingClientRect();dragging={pointer:e.pointerId,node,kind:handle?'panel':'fab',x:r.left,y:r.top,startX:e.clientX,startY:e.clientY,moved:false};
 (handle||fab).setPointerCapture?.(e.pointerId);
});
document.addEventListener('pointermove',e=>{
 if(!dragging||dragging.pointer!==e.pointerId)return;
 const d=dragging,dx=e.clientX-d.startX,dy=e.clientY-d.startY;if(Math.abs(dx)+Math.abs(dy)>5)d.moved=true;
 if(!d.moved)return;if(e.cancelable)e.preventDefault();
 const x=Math.max(0,Math.min(innerWidth-d.node.offsetWidth,d.x+dx));const y=Math.max(0,Math.min(innerHeight-d.node.offsetHeight,d.y+dy));
 d.node.style.left=x+'px';d.node.style.top=y+'px';d.node.style.right='auto';d.node.style.bottom='auto';
 if(d.kind==='panel')ui.chatPos={x,y};else ui.chatFabPos={x,y};
});
document.addEventListener('pointerup',e=>{
 if(!dragging||dragging.pointer!==e.pointerId)return;
 if(dragging.kind==='fab'&&dragging.moved)ignoreFabClick=true;
 try{localStorage.setItem('smartdecision_v3_chatpos',JSON.stringify(ui.chatPos));localStorage.setItem('smartdecision_v4_chatfabpos',JSON.stringify(ui.chatFabPos));}catch{}
 dragging=null;
});
document.addEventListener('pointercancel',()=>{dragging=null;});

render();
